steps.run:
O="$AGENT_HOME/work/bili.log"; : > "$O"; exec >>"$O" 2>&1
echo "== SHELL $SHELL"
echo "== 1 node"; node -v || { echo STOP_NONODE; exit 0; }
M=$(node -v | sed 's/^v//; s/\..*//'); [ "$M" -ge 22 ] || { echo STOP_OLDNODE; exit 0; }
echo "== 2 claude"; command -v claude || "$SHELL" -ilc 'command -v claude' || { echo STOP_NOCLAUDE; exit 0; }
echo "== 3 install"; npm install -g billion-context --prefix=~/.local || { echo INSTALL_FAILED; exit 0; }
echo "== 4 path"; "$SHELL" -ilc 'command -v bili' || echo BILI_NOT_IN_LOGIN_PATH
case "$SHELL" in *zsh) RC="$HOME/.zshrc";; *bash) RC="$HOME/.bashrc";; *) RC="";; esac
L='export PATH="$HOME/.local/bin:$PATH"'
if [ -n "$RC" ]; then if grep -qF "$L" "$RC" 2>/dev/null; then echo "RC_HAS_LINE $RC"; elif "$SHELL" -ilc 'command -v bili' >/dev/null 2>&1; then echo "RC_NOT_NEEDED"; else echo "$L" >> "$RC" && echo "RC_ADDED $RC" || echo "RC_WRITE_FAILED $RC"; fi; fi
echo "== 5 version"; ~/.local/bin/bili --version
echo DONE

cat "$AGENT_HOME/work/bili.log"
